<!doctype html><html lang="id" translate="no" class="notranslate"><head><meta charset="utf-8"><meta name="google" content="notranslate"><meta name="viewport" content="width=device-width,initial-scale=1"><title><?=e($ticket['ticket_number'])?></title><link rel="stylesheet" href="/assets/app.css?v=<?=e((string)filemtime(__DIR__.'/../../public/assets/app.css'))?>"><style><?=theme_css_vars()?></style></head><body class="auto-print"><main class="ticket"><h2><?=nl2br(e(setting('ticket_header',app_name())))?></h2><p><?=e($ticket['service_name'])?></p><?php if($ticket['sub_service_name']):?><p class="ticket-subservice"><?=e($ticket['sub_service_name'])?></p><?php endif?><strong><?=e($ticket['ticket_number'])?></strong><p><?=e(date('d/m/Y H:i',strtotime($ticket['created_at'])))?></p><hr><p><?=nl2br(e(setting('ticket_footer','Mohon menunggu nomor Anda dipanggil.')))?></p></main><section class="print-fallback-panel" id="print-fallback-panel" hidden><p>Karena tidak ada printer terhubung, Anda dapat mengunduh/menyimpan nomor antrean di bawah ini.</p><a class="button" id="print-fallback" href="<?=e(parse_url($_SERVER['REQUEST_URI'],PHP_URL_PATH).'.pdf')?>" download="<?=e($ticket['ticket_number'])?>.pdf">Download / Simpan Tiket PDF</a></section><div class="printing-message" id="printing-message">Mencetak tiket antrean…</div><script>
const ticketData=<?=json_encode(['ticket_header'=>setting('ticket_header',app_name()),'ticket_footer'=>setting('ticket_footer','Mohon menunggu nomor Anda dipanggil.'),'service_name'=>$ticket['service_name'],'sub_service_name'=>$ticket['sub_service_name'],'ticket_number'=>$ticket['ticket_number'],'created_at'=>date('d/m/Y H:i',strtotime($ticket['created_at']))],JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES)?>,message=document.querySelector('#printing-message'),fallbackPanel=document.querySelector('#print-fallback-panel'),fallback=document.querySelector('#print-fallback'),back=()=>location.replace('/kiosk?directprint=1');
async function directPrint(){const controller=new AbortController(),timeout=setTimeout(()=>controller.abort(),2500);try{const response=await fetch('http://127.0.0.1:17321/print',{method:'POST',headers:{'Content-Type':'text/plain;charset=UTF-8'},body:JSON.stringify(ticketData),signal:controller.signal});if(!response.ok)throw new Error('Print agent unavailable');message.textContent='Tiket berhasil dicetak';setTimeout(back,700)}catch(error){message.hidden=true;fallbackPanel.hidden=false}finally{clearTimeout(timeout)}}
fallback.addEventListener('click',()=>setTimeout(back,1200));
addEventListener('afterprint',back);addEventListener('load',()=>setTimeout(()=>localStorage.getItem('reka-direct-print')==='1'?directPrint():print(),150));setTimeout(()=>{if(fallbackPanel.hidden)back()},15000);
</script></body></html>
